mkdir -p /tmp/recon && cat > /tmp/recon/run.py <<'EOF'
import json,time,urllib.request,urllib.error
from datetime import datetime,timezone
B="http://localhost:8080"; tok=None; log={"codes":{}}
def req(path,method="GET",auth=True):
    global tok
    while True:
        h={}
        if auth:
            if not tok: tok=req("/token","POST",False)["token"]
            h["Authorization"]="Bearer "+tok
        r=urllib.request.Request(B+path,method=method,headers=h)
        try:
            with urllib.request.urlopen(r,timeout=30) as f: return json.load(f)
        except urllib.error.HTTPError as e:
            log["codes"][e.code]=log["codes"].get(e.code,0)+1
            if e.code==401: tok=None; continue
            if e.code==429: time.sleep(float(e.headers.get("Retry-After") or 1)); continue
            if e.code==404 and path.startswith("/customers"): return None
            time.sleep(0.5); continue
        except Exception: time.sleep(0.5); continue
orders={};dups=0;path="/orders?page=1";pages=0
while path:
    d=req(path);pages+=1
    for o in d["items"]:
        if o["id"] in orders: dups+=1
        else: orders[o["id"]]=o
    path=d["next"]
lo=datetime(2025,3,1,tzinfo=timezone.utc);hi=datetime(2025,6,1,tzinfo=timezone.utc)
cust={};reg={k:0 for k in["north","south","east","west"]};n=0;odd=[]
statuses={}
for o in orders.values():
    statuses[o["status"]]=statuses.get(o["status"],0)+1
    if o["status"]!="shipped": continue
    s=o["placed_at"].replace("Z","+00:00");t=datetime.fromisoformat(s)
    if t.tzinfo is None: odd.append(("naive",o["id"],s)); t=t.replace(tzinfo=timezone.utc)
    t=t.astimezone(timezone.utc)
    if not(lo<=t<hi): continue
    c=o["customer_id"]
    if c not in cust: cust[c]=req(f"/customers/{c}")
    cu=cust[c]
    if cu is None: odd.append(("nocust",o["id"],c)); continue
    a=o["amount_cents"]*(100-cu["discount_pct"]); v=(a+50)//100
    if a<0: odd.append(("neg",o["id"],a))
    reg[cu["region"]]+=v;n+=1
res={"total_cents":sum(reg.values()),"order_count":n,"duplicates_skipped":dups,"by_region":reg}
json.dump(res,open("/workspace/result.json","w"),indent=2)
print(res,pages,len(orders),statuses,log,odd[:20],len(odd))
EOF
python3 -I /tmp/recon/run.py

